using System;using System.IO;using UnityEngine;using UnityEditor;
// Explicit review-only importer. Runtime catalog/assets outside review folder untouched.
public static class FullRosterDenseImport {
 public static void Run(){int exit=1;try{string role=Environment.GetEnvironmentVariable("LF_DENSE_ROLE")??"master";if(!System.Text.RegularExpressions.Regex.IsMatch(role,"^[a-z]+$"))throw new Exception("Invalid role");string path="Assets/Native67SpatialReview/"+char.ToUpperInvariant(role[0])+role.Substring(1)+"DenseReview.fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var m=(ModelImporter)AssetImporter.GetAtPath(path);m.animationType=ModelImporterAnimationType.Generic;m.avatarSetup=ModelImporterAvatarSetup.NoAvatar;m.importAnimation=false;m.optimizeGameObjects=false;m.isReadable=true;m.meshCompression=ModelImporterMeshCompression.Off;m.skinWeights=ModelImporterSkinWeights.Custom;m.maxBonesPerVertex=255;m.minBoneWeight=0;m.importNormals=ModelImporterNormals.Import;m.importTangents=ModelImporterTangents.Import;m.optimizeMeshPolygons=false;m.optimizeMeshVertices=false;m.weldVertices=false;m.SaveAndReimport();Debug.Log("AGENT_RESULT review_import_configured "+role+" raw Float32 oracle remains coefficient authority");exit=0;}catch(Exception e){Debug.LogException(e);}finally{EditorApplication.Exit(exit);}}
}
